# id: zebra-solver-v1
DESCRIPTION = "ZebraLogic constraint solver: parses the puzzle's own categories and numbered clues, disambiguates values shared across categories, runs propagation plus backtracking with load caps, re-verifies every clue, and returns the house-by-attribute table plus same-house chains; emits nothing when no unique verified solution is found."

MAX_COMBOS = 512
MAX_NODES = 150000

_WORDNUM = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10}
_ORD = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8, "ninth": 9, "tenth": 10}


class _Cap(Exception):
