        out.append(cur.lower())
    return out


def _stem(t):
    if t.endswith("s") and len(t) > 3:
        return t[:-1]
    return t


def _parse(q):
    i = q.find("There are ")
    if i < 0:
        return None
    rest = q[i + 10:]
    num = ""
    for ch in rest:
        if ch.isdigit():
            num += ch
        else:
            break
    if not num:
        return None
    n = int(num)
    if not (2 <= n <= 8):
        return None
    cats = []
    for line in q.split("\n"):
        ls = line.strip()
        if ls.startswith("- ") and "`" in ls and ":" in ls:
            vals = []
            parts = ls.split("`")
            for k in range(1, len(parts), 2):
                v = parts[k].strip()
                if v:
                    vals.append(v)
            if vals:
                cats.append(vals)
    if not cats:
        return None
    for c in cats:
        if len(c) != n:
            return None
    ci = q.find("## Clues")
    if ci < 0:
        return None
    clues = []
    for line in q[ci:].split("\n"):
        ls = line.strip()
        if ". " in ls:
            head, tail = ls.split(". ", 1)
            if head.isdigit():
                clues.append((int(head), tail.strip()))
