def _mentions(txt, seq, mx):
    toks = _tokens(txt)
    st = [_stem(t) for t in toks]
    out = []
    i = 0
    while i < len(toks):
        hit = None
        for L in range(min(mx, len(toks) - i), 0, -1):
            k = tuple(toks[i:i + L])
            if k in seq:
                hit = k
                break
            k2 = tuple(st[i:i + L])
            if k2 in seq:
                hit = k2
                break
        if hit is not None:
            out.append(seq[hit])
            i += len(hit)
        else:
            i += 1
    return out


def _house_after(s, key):
    j = s.find(key)
    if j < 0:
        return None
    tail = s[j + len(key):].split("house")[0]
    toks = _tokens(tail)
    if not toks:
        return None
    t = toks[0]
    if t in _ORD:
        return _ORD[t]
    if t in _WORDNUM:
        return _WORDNUM[t]
    if t.isdigit():
        return int(t)
    if len(t) > 2 and t[:-2].isdigit():
        return int(t[:-2])
    return None


def _parse_clue(txt, seq, mx):
    s = txt.lower()
    m = _mentions(txt, seq, mx)
    if "houses between" in s or "house between" in s:
        if len(m) != 2:
            return None
        cnt = None
        for w, d in _WORDNUM.items():
            if (" " + w + " house") in s or (" " + w + " houses") in s:
                cnt = d
        for d in range(1, 10):
            if (" " + str(d) + " house") in s or (" " + str(d) + " houses") in s:
                cnt = d
        if cnt is None:
            return None
        return ("dist", m[0], m[1], cnt + 1)
    if "not in the" in s and len(m) == 1:
        h = _house_after(s, "not in the")
        if h is not None:
            return ("fixneg", m[0], None, h)
    if " in the " in s and "to the" not in s and " house" in s and len(m) == 1:
        h = _house_after(s, " in the ")
        if h is not None:
            return ("fixpos", m[0], None, h)
    if "directly left of" in s:
        if len(m) != 2:
            return None
        return ("adj", m[0], m[1], 0)
    if "directly right of" in s:
        if len(m) != 2:
            return None
        return ("adj", m[1], m[0], 0)
    if "to the left of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[0], m[1], 0)
    if "to the right of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[1], m[0], 0)
    if "next to" in s:
        if len(m) != 2:
            return None
        return ("nextto", m[0], m[1], 0)
    if " is not " in s:
        if len(m) != 2:
            return None
        return ("neq", m[0], m[1], 0)
    if " is " in s:
        if len(m) != 2:
            return None
        return ("eq", m[0], m[1], 0)
    return None


def _choices(lists):
    if not lists:
        yield ()
        return
    idx = [0] * len(lists)
    while True:
        yield tuple(lists[i][idx[i]] for i in range(len(lists)))
        k = len(lists) - 1
        while k >= 0:
            idx[k] += 1
            if idx[k] < len(lists[k]):
                break
            idx[k] = 0
            k -= 1
        if k < 0:
            return


def _solve_all(n, cats, pclues):
    amb = []
    seen = set()
    for (_, _, pc) in pclues:
        ops = [pc[1]] + ([pc[2]] if pc[2] is not None else [])
        for op in ops:
            if len(op) > 1:
                key = tuple(sorted(op))
                if key not in seen:
                    seen.add(key)
                    amb.append(op)
    total = 1
    for op in amb:
        total *= len(op)
    if total > MAX_COMBOS:
        return None
    node = [MAX_NODES]
    sols = []
    for choice in _choices(amb):
        cmap = {}
        for op, c in zip(amb, choice):
            cmap[tuple(sorted(op))] = c
        r = _combo(n, pclues, cmap, node)
        if r is None:
            continue
        assign, clusters = r
        sig = tuple(sorted(assign.items()))
