    return assign, clusters, ambvals


def _combo(n, pclues, cmap, node):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    def res(op):
        if len(op) == 1:
            return op[0]
        return cmap[tuple(sorted(op))]

    for (_, _, pc) in pclues:
        if pc[0] == "eq":
            union(res(pc[1]), res(pc[2]))
    fixed = {}
    negs = {}
    cons = []
    for (_, _, pc) in pclues:
        t, a, b, d = pc
        if t == "fixpos":
            fixed[find(res(a))] = d - 1
        elif t == "fixneg":
            negs.setdefault(find(res(a)), set()).add(d - 1)
        elif t != "eq":
            cons.append((t, find(res(a)), find(res(b)), d))
    members = {}
    for e in list(parent):
        members.setdefault(find(e), []).append(e)
    dom = {}
    rootcats = {}
    for r, ms in members.items():
        cs = [e[0] for e in ms]
        if len(set(cs)) != len(cs):
            return None
        rootcats[r] = set(cs)
        dom[r] = set(range(n))
    for r, h in fixed.items():
        if r not in dom or not (0 <= h < n):
            return None
        dom[r] = {h}
    for r, hs in negs.items():
        if r in dom:
            dom[r] = dom[r] - hs
    for r in dom:
        if not dom[r]:
            return None
    sols = _search2(dom, cons, rootcats, node)
    if len(sols) != 1:
        return None
    pos = sols[0]
    for (_, _, pc) in pclues:
        if not _ok(pc, pos, res, find):
            return None
    assign = {}
    for r, ms in members.items():
        for e in ms:
            assign[e] = pos[r]
    return assign, list(members.values())


def _search2(dom0, cons, rootcats, node):
    sols = []

    def ac3(dom):
        changed = True
        while changed:
            changed = False
            for (t, a, b, d) in cons:
                da = dom.get(a)
                db = dom.get(b)
                if da is None or db is None:
                    continue
                if t == "adj":
                    na = set(x for x in da if x + 1 in db)
                    nb = set(x for x in db if x - 1 in da)
                elif t == "lt":
                    na = set(x for x in da if any(y > x for y in db))
                    nb = set(x for x in db if any(y < x for y in da))
                elif t == "nextto":
                    na = set(x for x in da if x + 1 in db or x - 1 in db)
                    nb = set(x for x in db if x + 1 in da or x - 1 in da)
                elif t == "dist":
                    na = set(x for x in da if x + d in db or x - d in db)
                    nb = set(x for x in db if x + d in da or x - d in da)
                else:
                    na = set(da)
                    nb = set(db)
                    if len(db) == 1:
                        na = set(x for x in da if x not in db)
                    if len(da) == 1:
                        nb = set(x for x in db if x not in da)
                if na != da or nb != db:
                    if not na or not nb:
                        return False
                    dom[a] = na
                    dom[b] = nb
                    changed = True
        return True

    def rec(dom, assign):
        if node[0] <= 0:
            raise _Cap()
        node[0] -= 1
        best = None
        for r in dom:
            if r not in assign and (best is None or len(dom[r]) < len(dom[best])):
                best = r
        if best is None:
            sols.append(dict(assign))
            return len(sols) >= 2
        for h in sorted(dom[best]):
            bad = False
            for o, hv in assign.items():
                if hv == h and (rootcats.get(o, set()) & rootcats.get(best, set())):
                    bad = True
                    break
            if bad:
                continue
            nd = dict(dom)
            nd[best] = {h}
            assign[best] = h
            try:
                if ac3(nd, cons):
                    if rec(nd, assign):
                        return True
            finally:
                del assign[best]
        return False

    d0 = dict(dom0)
    if not ac3(d0, cons):
        return []
    try:
