    except _Cap:
        return []
    return sols


def _ok(pc, pos, res, find):
    t, a, b, d = pc
    if t == "eq":
        return find(res(a)) == find(res(b))
    if t in ("fixpos", "fixneg"):
        h = pos[find(res(a))]
        return (h == d - 1) if t == "fixpos" else (h != d - 1)
    x = pos[find(res(a))]
    y = pos[find(res(b))]
    if t == "adj":
        return x == y - 1
    if t == "lt":
        return x < y
    if t == "nextto":
        return abs(x - y) == 1
    if t == "dist":
        return abs(x - y) == d
    if t == "neq":
