    grid = [["?"] * len(cats) for _ in range(n)]
    for (ci, vi), h in assign.items():
        if 0 <= h < n and 0 <= ci < len(cats):
            grid[h][ci] = cats[ci][vi]
    rows = [["House"] + [str(c) for c in cols]]
