            h = assign[ms[0]] + 1
            txt = "House %d: %s" % (h, " = ".join(cats[ci][vi] for (ci, vi) in ms))
            if len(txt) <= 200:
                chains.append(txt)
    facts.extend(chains[:12])
    for v in ambvals[:4]:
        warnings.append("Value '%s' appears in more than one category; the reading used here was selected by overall consistency." % v)
    if not facts and not warnings:
        return None
    return {"facts": facts, "warnings": warnings, "table": table}
