    if "to the left of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[0], m[1], 0)
    if "to the right of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[1], m[0], 0)
    if "next to" in s:
        if len(m) != 2:
            return None
        return ("nextto", m[0], m[1], 0)
    if " is not " in s:
        if len(m) != 2:
            return None
        return ("neq", m[0], m[1], 0)
    if " is " in s:
        if len(m) != 2:
            return None
        return ("eq", m[0], m[1], 0)
    return None


def _val(op, cats):
    if len(op) == 1:
        return cats[op[0][0]][op[0][1]]
    return None


def _fmt(num, pc, cats):
    t, a, b, d = pc
    va = _val(a, cats)
    if va is None:
        return None
    if t == "fixpos":
        return "Clue %d: %s is in house %d." % (num, va, d)
    if t == "fixneg":
        return "Clue %d: %s is not in house %d." % (num, va, d)
    vb = _val(b, cats)
    if vb is None:
        return None
    if t == "adj":
        return "Clue %d: %s is directly left of %s." % (num, va, vb)
    if t == "lt":
        return "Clue %d: %s is somewhere to the left of %s." % (num, va, vb)
    if t == "nextto":
        return "Clue %d: %s is next to %s." % (num, va, vb)
    if t == "dist":
        return "Clue %d: there are %d houses between %s and %s." % (num, d - 1, va, vb)
    if t == "neq":
        return "Clue %d: %s is not %s." % (num, va, vb)
    if t == "eq":
        return "Clue %d: %s and %s are the same person." % (num, va, vb)
    return None


def _run(view):
    q = view.get("question") or ""
    p = _parse(q)
    if not p:
        return None
    n, cats, clue_list = p
    seq, mx = _index(cats)
    facts = []
    total = 0
    for (num, txt) in clue_list:
        pc = _parse_clue(txt, seq, mx)
        if pc is None:
            return None
        f = _fmt(num, pc, cats)
        if f is None:
            return None
        if len(f) <= 200 and total + len(f) + 1 <= 1500:
            facts.append(f)
            total += len(f) + 1
    if not facts:
        return None
    return {"facts": facts, "warnings": [], "table": None}
