```python
DESCRIPTION = "ZebraLogic constraint solver: parses the puzzle's own categories and numbered clues, disambiguates values shared across categories, runs propagation plus backtracking with load caps, re-verifies every clue, and returns the house-by-attribute table plus same-house chains; emits nothing when no unique verified solution is found."

MAX_COMBOS = 512
MAX_NODES = 150000

_WORDNUM = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9, "ten": 10}
_ORD = {"first": 1, "second": 2, "third": 3, "fourth": 4, "fifth": 5, "sixth": 6, "seventh": 7, "eighth": 8, "ninth": 9, "tenth": 10}


class _Cap(Exception):
    pass


def applies(view):
    try:
        q = view.get("question") or ""
        return "## Clues" in q and "houses" in q and "`" in q
    except Exception:
        return False


def before_call(view, state):
    try:
        return _run(view)
    except Exception:
        return None


def _tokens(s):
    out = []
    cur = ""
    for ch in s:
        if ch.isalnum():
            cur += ch
        else:
            if cur:
                out.append(cur.lower())
            cur = ""
    if cur:
        out.append(cur.lower())
    return out


def _stem(t):
    if t.endswith("s") and len(t) > 3:
        return t[:-1]
    return t


def _parse(q):
    i = q.find("There are ")
    if i < 0:
        return None
    rest = q[i + 10:]
    num = ""
    for ch in rest:
        if ch.isdigit():
            num += ch
        else:
            break
    if not num:
        return None
    n = int(num)
    if not (2 <= n <= 8):
        return None
    cats = []
    for line in q.split("\n"):
        ls = line.strip()
        if ls.startswith("- ") and "`" in ls and ":" in ls:
            vals = []
            parts = ls.split("`")
            for k in range(1, len(parts), 2):
                v = parts[k].strip()
                if v:
                    vals.append(v)
            if vals:
                cats.append(vals)
    if not cats:
        return None
    for c in cats:
        if len(c) != n:
            return None
    ci = q.find("## Clues")
    if ci < 0:
        return None
    clues = []
    for line in q[ci:].split("\n"):
        ls = line.strip()
        if ". " in ls:
            head, tail = ls.split(". ", 1)
            if head.isdigit():
                clues.append((int(head), tail.strip()))
    if not clues:
        return None
    return n, cats, clues


def _index(cats):
    seq = {}
    mx = 1
    for ci, c in enumerate(cats):
        for vi, v in enumerate(c):
            t = tuple(_tokens(v))
            if not t:
                continue
            seq.setdefault(t, []).append((ci, vi))
            st = tuple(_stem(x) for x in t)
            if st != t:
                seq.setdefault(st, []).append((ci, vi))
            if len(t) > mx:
                mx = len(t)
    return seq, mx


def _mentions(txt, seq, mx):
    toks = _tokens(txt)
    st = [_stem(t) for t in toks]
    out = []
    i = 0
    while i < len(toks):
        hit = None
        for L in range(min(mx, len(toks) - i), 0, -1):
            k = tuple(toks[i:i + L])
            if k in seq:
                hit = k
                break
            k2 = tuple(st[i:i + L])
            if k2 in seq:
                hit = k2
                break
        if hit is not None:
            out.append(seq[hit])
            i += len(hit)
        else:
            i += 1
    return out


def _house_after(s, key):
    j = s.find(key)
    if j < 0:
        return None
    tail = s[j + len(key):].split("house")[0]
    toks = _tokens(tail)
    if not toks:
        return None
    t = toks[0]
    if t in _ORD:
        return _ORD[t]
    if t in _WORDNUM:
        return _WORDNUM[t]
    if t.isdigit():
        return int(t)
    if len(t) > 2 and t[:-2].isdigit():
        return int(t[:-2])
    return None


def _parse_clue(txt, seq, mx):
    s = txt.lower()
    m = _mentions(txt, seq, mx)
    if "houses between" in s or "house between" in s:
        if len(m) != 2:
            return None
        cnt = None
        for w, d in _WORDNUM.items():
            if (" " + w + " house") in s or (" " + w + " houses") in s:
                cnt = d
        for d in range(1, 10):
            if (" " + str(d) + " house") in s or (" " + str(d) + " houses") in s:
                cnt = d
        if cnt is None:
            return None
        return ("dist", m[0], m[1], cnt + 1)
    if "not in the" in s and len(m) == 1:
        h = _house_after(s, "not in the")
        if h is not None:
            return ("fixneg", m[0], None, h)
    if " in the " in s and "to the" not in s and " house" in s and len(m) == 1:
        h = _house_after(s, " in the ")
        if h is not None:
            return ("fixpos", m[0], None, h)
    if "directly left of" in s:
        if len(m) != 2:
            return None
        return ("adj", m[0], m[1], 0)
    if "directly right of" in s:
        if len(m) != 2:
            return None
        return ("adj", m[1], m[0], 0)
    if "to the left of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[0], m[1], 0)
    if "to the right of" in s:
        if len(m) != 2:
            return None
        return ("lt", m[1], m[0], 0)
    if "next to" in s:
        if len(m) != 2:
            return None
        return ("nextto", m[0], m[1], 0)
    if " is not " in s:
        if len(m) != 2:
            return None
        return ("neq", m[0], m[1], 0)
    if " is " in s:
        if len(m) != 2:
            return None
        return ("eq", m[0], m[1], 0)
    return None


def _choices(lists):
    if not lists:
        yield ()
        return
    idx = [0] * len(lists)
    while True:
        yield tuple(lists[i][idx[i]] for i in range(len(lists)))
        k = len(lists) - 1
        while k >= 0:
            idx[k] += 1
            if idx[k] < len(lists[k]):
                break
            idx[k] = 0
            k -= 1
        if k < 0:
            return


def _solve_all(n, cats, pclues):
    amb = []
    seen = set()
    for (_, _, pc) in pclues:
        ops = [pc[1]] + ([pc[2]] if pc[2] is not None else [])
        for op in ops:
            if len(op) > 1:
                key = tuple(sorted(op))
                if key not in seen:
                    seen.add(key)
                    amb.append(op)
    total = 1
    for op in amb:
        total *= len(op)
    if total > MAX_COMBOS:
        return None
    node = [MAX_NODES]
    sols = []
    for choice in _choices(amb):
        cmap = {}
        for op, c in zip(amb, choice):
            cmap[tuple(sorted(op))] = c
        r = _combo(n, pclues, cmap, node)
        if r is None:
            continue
        assign, clusters = r
        sig = tuple(sorted(assign.items()))
        if any(s[0] == sig for s in sols):
            continue
        sols.append((sig, assign, clusters))
        if len(sols) > 1:
            return None
    if len(sols) != 1:
        return None
    _, assign, clusters = sols[0]
    ambvals = sorted(set(c[1] for op in amb for c in op))
    return assign, clusters, ambvals


def _combo(n, pclues, cmap, node):
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        r = x
        while parent[r] != r:
            r = parent[r]
        while parent[x] != r:
            parent[x], x = r, parent[x]
        return r

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb

    def res(op):
        if len(op) == 1:
            return op[0]
        return cmap[tuple(sorted(op))]

    for (_, _, pc) in pclues:
        if pc[0] == "eq":
            union(res(pc[1]), res(pc[2]))
    fixed = {}
    negs = {}
    cons = []
    for (_, _, pc) in pclues:
        t, a, b, d = pc
        if t == "fixpos":
            fixed[find(res(a))] = d - 1
        elif t == "fixneg":
            negs.setdefault(find(res(a)), set()).add(d - 1)
        elif t != "eq":
            cons.append((t, find(res(a)), find(res(b)), d))
    members = {}
    for e in list(parent):
        members.setdefault(find(e), []).append(e)
    dom = {}
    rootcats = {}
    for r, ms in members.items():
        cs = [e[0] for e in ms]
        if len(set(cs)) != len(cs):
            return None
        rootcats[r] = set(cs)
        dom[r] = set(range(n))
    for r, h in fixed.items():
        if r not in dom or not (0 <= h < n):
            return None
        dom[r] = {h}
    for r, hs in negs.items():
        if r in dom:
            dom[r] = dom[r] - hs
    for r in dom:
        if not dom[r]:
            return None
    sols = _search2(dom, cons, rootcats, node)
    if len(sols) != 1:
        return None
    pos = sols[0]
    for (_, _, pc) in pclues:
        if not _ok(pc, pos, res, find):
            return None
    assign = {}
    for r, ms in members.items():
        for e in ms:
            assign[e] = pos[r]
    return assign, list(members.values())


def _search2(dom0, cons, rootcats, node):
    sols = []

    def ac3(dom):
        changed = True
        while changed:
            changed = False
            for (t, a, b, d) in cons:
                da = dom.get(a)
                db = dom.get(b)
                if da is None or db is None:
                    continue
                if t == "adj":
                    na = set(x for x in da if x + 1 in db)
                    nb = set(x for x in db if x - 1 in da)
                elif t == "lt":
                    na = set(x for x in da if any(y > x for y in db))
                    nb = set(x for x in db if any(y < x for y in da))
                elif t == "nextto":
                    na = set(x for x in da if x + 1 in db or x - 1 in db)
                    nb = set(x for x in db if x + 1 in da or x - 1 in da)
                elif t == "dist":
                    na = set(x for x in da if x + d in db or x - d in db)
                    nb = set(x for x in db if x + d in da or x - d in da)
                else:
                    na = set(da)
                    nb = set(db)
                    if len(db) == 1:
                        na = set(x for x in da if x not in db)
                    if len(da) == 1:
                        nb = set(x for x in db if x not in da)
                if na != da or nb != db:
                    if not na or not nb:
                        return False
                    dom[a] = na
                    dom[b] = nb
                    changed = True
        return True

    def rec(dom, assign):
        if node[0] <= 0:
            raise _Cap()
        node[0] -= 1
        best = None
        for r in dom:
            if r not in assign and (best is None or len(dom[r]) < len(dom[best])):
                best = r
        if best is None:
            sols.append(dict(assign))
            return len(sols) >= 2
        for h in sorted(dom[best]):
            bad = False
            for o, hv in assign.items():
                if hv == h and (rootcats.get(o, set()) & rootcats.get(best, set())):
                    bad = True
                    break
            if bad:
                continue
            nd = dict(dom)
            nd[best] = {h}
            assign[best] = h
            try:
                if ac3(nd, cons):
                    if rec(nd, assign):
                        return True
            finally:
                del assign[best]
        return False

    d0 = dict(dom0)
    if not ac3(d0, cons):
        return []
    try:
        rec(d0, {})
    except _Cap:
        return []
    return sols


def _ok(pc, pos, res, find):
    t, a, b, d = pc
    if t == "eq":
        return find(res(a)) == find(res(b))
    if t in ("fixpos", "fixneg"):
        h = pos[find(res(a))]
        return (h == d - 1) if t == "fixpos" else (h != d - 1)
    x = pos[find(res(a))]
    y = pos[find(res(b))]
    if t == "adj":
        return x == y - 1
    if t == "lt":
        return x < y
    if t == "nextto":
        return abs(x - y) == 1
    if t == "dist":
        return abs(x - y) == d
    if t == "neq":
        return x != y
    return False


def _make_table(view, n, cats, assign):
    cols = view.get("columns") or []
    if len(cols) != len(cats):
        return None
    grid = [["?"] * len(cats) for _ in range(n)]
    for (ci, vi), h in assign.items():
        if 0 <= h < n and 0 <= ci < len(cats):
            grid[h][ci] = cats[ci][vi]
    rows = [["House"] + [str(c) for c in cols]]
    for i in range(n):
        rows.append([str(i + 1)] + grid[i])
    if any("?" in r for r in rows[1:]):
        return None
    return rows


def _run(view):
    q = view.get("question") or ""
    p = _parse(q)
    if not p:
        return None
    n, cats, clue_list = p
    seq, mx = _index(cats)
    pclues = []
    for (num, txt) in clue_list:
        pc = _parse_clue(txt, seq, mx)
        if pc is None:
            return None
        pclues.append((num, txt, pc))
    sol = _solve_all(n, cats, pclues)
    if sol is None:
        return None
    assign, clusters, ambvals = sol
    facts = []
    warnings = []
    table = _make_table(view, n, cats, assign)
    if table is not None:
        facts.append("Verified: the assignment in the table was re-checked against every numbered clue of this puzzle and satisfies all of them.")
    else:
        warnings.append("A unique consistent assignment was found for the parsed clues, but not every table cell is determined; only same-house chains are reported.")
    chains = []
    for ms in clusters:
        if len(ms) >= 2:
            h = assign[ms[0]] + 1
            txt = "House %d: %s" % (h, " = ".join(cats[ci][vi] for (ci, vi) in ms))
            if len(txt) <= 200:
                chains.append(txt)
    facts.extend(chains[:12])
    for v in ambvals[:4]:
        warnings.append("Value '%s' appears in more than one category; the reading used here was selected by overall consistency." % v)
    if not facts and not warnings:
        return None
    return {"facts": facts, "warnings": warnings, "table": table}
